}

export default async function(self, env, ctx) {
  for (const e of ["view_section_spm_sla","monitoring_transactions","monitoring_transaction_details","toll_sections","toll_gates","shift_schedules","m_section_shifts","m_spm","m_sla","spm_sla"]) {
    try {
      const d = await env.TROM.describe_entity(e);
      console.log("=== "+e+" ===");
      console.log(JSON.stringify(d.fields.map(f=>({n:f.name,t:f.type,desc:f.description})),null,1));
      console.log("PK:"+JSON.stringify(d.primary_key));
    } catch(err){ console.log("ERR "+e+": "+err.message); }
  }
}

