export default async function(self, env, ctx) {
  let gates = await env.TROM.read_records("toll_gates", ["id","gate_name","section_id","total_booth"], [{field:"section_id",operator:"eq",value:1}], [], 100, null);
  console.log(JSON.stringify(gates.records,null,1));
  let sched = await env.TROM.read_records("shift_schedules", ["id","section_id","shift","date","shift_id","start_hour","end_hour"], [{field:"section_id",operator:"eq",value:1}], [], 100, null);
  // filter date manually
  console.log("SCHED count page:"+sched.records.length+" next:"+sched.next_cursor);
  console.log(JSON.stringify(sched.records.filter(r=>r.date==="2026-06-01"),null,1));
  console.log(JSON.stringify(sched.records.slice(0,5),null,1));
}

export default async function(self, env, ctx) {
  // monitoring transactions for section 1 gate 33 date 2026-06-01
  let mt = await env.TROM.read_records("monitoring_transactions",
    ["id","section_id","gate_id","date","schedule_id","description","total_booth","status_code"],
    [{field:"section_id",operator:"eq",value:1},{field:"gate_id",operator:"eq",value:33},{field:"date",operator:"eq",value:"2026-06-01"}],
    [], 100, null);
  console.log("MT:"+JSON.stringify(mt.records,null,1));

  // shift schedules for section 1 date 2026-06-01
  let ss = await env.TROM.read_records("shift_schedules",
    ["id","section_id","shift","date","shift_id","start_hour","end_hour"],
    [{field:"section_id",operator:"eq",value:1},{field:"date",operator:"eq",value:"2026-06-01"}],
    [], 100, null);
  console.log("SS:"+JSON.stringify(ss.records,null,1));

  // view_section_spm_sla for section 1 codes kecepatan-transaksi-1..5
  let v = await env.TROM.read_records("view_section_spm_sla",
    ["section_id","spm_id","code","indicator","operator","spm_parameter","sla_parameter","is_applicable","unit"],
    [{field:"section_id",operator:"eq",value:1},{field:"code",operator:"in",value:["kecepatan-transaksi-1","kecepatan-transaksi-2","kecepatan-transaksi-3","kecepatan-transaksi-4","kecepatan-transaksi-5"]}],
    [{field:"code",direction:"asc"}], 100, null);
  console.log("VIEW:"+JSON.stringify(v.records,null,1));
}

export default async function(self, env, ctx) {
  let d = await env.TROM.read_records("monitoring_transaction_details",
    ["id","transaction_id","type","booth_number","sample_number","vehicle_queue","transaction_duration","vehicle_type","vehicle_class_id","payment_id"],
    [{field:"transaction_id",operator:"eq",value:1600800001}],
    [{field:"booth_number",direction:"asc"},{field:"id",direction:"asc"}], 500, null);
  console.log("COUNT details first page: "+d.records.length+" next:"+d.next_cursor);
  console.log(JSON.stringify(d.records,null,1));
  if (d.next_cursor) {
    let d2 = await env.TROM.read_records("monitoring_transaction_details",
      ["id","transaction_id","type","booth_number","sample_number","vehicle_queue","transaction_duration","vehicle_type","vehicle_class_id","payment_id"],
      [{field:"transaction_id",operator:"eq",value:1600800001}],
      [{field:"booth_number",direction:"asc"},{field:"id",direction:"asc"}], 500, d.next_cursor);
    console.log("PAGE2: "+d2.records.length);
    console.log(JSON.stringify(d2.records,null,1));
  }
}

export default async function(self, env, ctx) {
  let m = await env.TROM.read_records("m_spm",
    ["id","code","indicator","sub_indicator","description","operator","spm_parameter","unit","is_static"],
    [{field:"code",operator:"in",value:["kecepatan-transaksi-1","kecepatan-transaksi-2","kecepatan-transaksi-3","kecepatan-transaksi-4","kecepatan-transaksi-5"]}],
    [{field:"code",direction:"asc"}], 50, null);
  console.log(JSON.stringify(m.records,null,1));
  let v = await env.TROM.read_records("view_section_spm_sla",
    ["section_id","spm_id","code","indicator","sub_indicator","description","is_static","spm_specification","sla_specification","operator","spm_parameter","sla_parameter","unit","is_applicable","score_default"],
    [{field:"section_id",operator:"eq",value:1},{field:"code",operator:"in",value:["kecepatan-transaksi-1","kecepatan-transaksi-2","kecepatan-transaksi-3","kecepatan-transaksi-4","kecepatan-transaksi-5"]}],
    [{field:"code",direction:"asc"}], 50, null);
  console.log(JSON.stringify(v.records,null,1));
  // spm_sla table for this monitoring? check module
  let s = await env.TROM.read_records("spm_sla",
    ["id","section_id","spm_id","schedule_id","date","operator","spm_parameter","sla_parameter","unit","score","is_spm_passed","is_sla_passed","module_name","module_id","is_applicable"],
    [{field:"section_id",operator:"eq",value:1},{field:"date",operator:"eq",value:"2026-06-01"}],
    [], 100, null);
  console.log("SPM_SLA:"+JSON.stringify(s.records,null,1));
}
